1	/**
2	 * Generic @-mention support for marginalia comments. Personas are the only
3	 * mentionable kind today; human collaborators are a planned addition — they
4	 * slot in by appending another `Mentionable[]` to the candidate list (see
5	 * `CommentsPanel`'s `collaborators` prop), no changes needed here.
6	 */
7	
8	export type MentionKind = "persona" | "collaborator";
9	
10	export interface Mentionable {
11	  id: string;
12	  name: string;
13	  kind: MentionKind;
14	  icon?: string;
15	  color?: string;
16	}
17	
18	/** The partial name being typed after a trailing "@", if any. */
19	export function activeMentionQuery(value: string): string | null {
20	  const match = value.match(/@([A-Za-z]*)$/);
21	  return match ? match[1] : null;
22	}
23	
24	/** Replace the trailing partial "@query" with the full "@Name ". */
25	export function applyMention(value: string, name: string): string {
26	  return value.replace(/@([A-Za-z]*)$/, `@${name} `);
27	}
28	
29	export function filterMentionables(
30	  items: Mentionable[],
31	  query: string,
32	): Mentionable[] {
33	  const q = query.toLowerCase();
34	  return items.filter((item) => item.name.toLowerCase().startsWith(q));
35	}
36	
37	function escapeRegExp(s: string): string {
38	  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
39	}
40	
41	/** Mentionables @-named (whole word) anywhere in the text. */
42	export function mentionedIn(
43	  text: string,
44	  items: Mentionable[],
45	): Mentionable[] {
46	  return items.filter((item) =>
47	    new RegExp(`@${escapeRegExp(item.name)}\\b`, "i").test(text),
48	  );
49	}
