86	export function parseShortcut(shortcut: string): ParsedShortcut {
87	  const parts = shortcut.split("-").filter(Boolean);
88	  const key = parts.pop() ?? "";
89	  return {
90	    modifiers: parts.filter((part) => VALID_MODIFIERS.has(part)),
91	    key,
92	  };
