95	function displayKey(key: string, platform: ShortcutPlatform): string {
96	  const named: Record<string, string> = {
97	    Enter: platform === "mac" ? "↩" : "Enter",
98	    Tab: platform === "mac" ? "⇥" : "Tab",
99	    Escape: platform === "mac" ? "Esc" : "Esc",
100	    Backspace: platform === "mac" ? "⌫" : "Backspace",
101	    Delete: platform === "mac" ? "⌦" : "Delete",
102	    ArrowUp: "↑",
103	    ArrowDown: "↓",
104	    ArrowLeft: "←",
105	    ArrowRight: "→",
106	    Space: "Space",
107	  };
108	  if (named[key]) return named[key];
109	  return key.length === 1 ? key.toLocaleUpperCase() : key;
110	}
