112	/** Human-readable labels for tooltips, the shortcut dialog, and the Manual. */
113	export function formatShortcut(
114	  shortcut: string,
115	  platform: ShortcutPlatform = shortcutPlatform(),
116	): string {
117	  const parsed = parseShortcut(shortcut);
118	  const modifierMap = platform === "mac" ? MAC_MODIFIERS : OTHER_MODIFIERS;
119	  const modifiers = parsed.modifiers.map((part) => modifierMap[part] ?? part);
120	  const key = displayKey(parsed.key, platform);
121	  return platform === "mac"
122	    ? `${modifiers.join("")}${key}`
123	    : [...modifiers, key].filter(Boolean).join("+");
124	}
