134	/**
135	 * Minimal subset of `KeyboardEvent` we need to recognise a chord. Keeps the
136	 * matcher testable without pulling in a DOM, and lets the keyboard handler in
137	 * `twyne-editor.tsx` consult the registry instead of hard-coding per-command
138	 * `if (key === "x")` branches.
139	 */
140	export interface ChordEvent {
141	  /** Lowercased `KeyboardEvent.key`, e.g. `"f"`, `"/"`, `"?"`. */
142	  key: string;
143	  metaKey?: boolean;
144	  ctrlKey?: boolean;
145	  altKey?: boolean;
146	  shiftKey?: boolean;
147	}
148	
149	/**
150	 * Does this keyboard event satisfy the given chord? Modifiers are matched as
151	 * a set: `Mod` accepts whichever of `metaKey`/`ctrlKey` is the platform's
152	 * primary modifier (caller decides by passing `metaKey: true` for ⌘ and
153	 * `ctrlKey: true` for Ctrl). Plain `Tab` / `Shift-Tab` chords ignore the
154	 * modifier check entirely.
155	 */
156	export function chordMatches(event: ChordEvent, shortcut: string): boolean {
157	  const parsed = parseShortcut(shortcut);
158	  const wantsMod = parsed.modifiers.includes("Mod");
159	  const wantsCtrl = parsed.modifiers.includes("Ctrl");
160	  const wantsAlt = parsed.modifiers.includes("Alt");
161	  const wantsShift = parsed.modifiers.includes("Shift");
162	
163	  // `Mod` is the cross-platform primary modifier (⌘ on macOS, Ctrl elsewhere).
164	  // `Ctrl` is the literal control key — distinct so a future Linux binding can
165	  // use it without colliding with `Mod`. Either alone satisfies the event.
166	  const primary = event.metaKey || event.ctrlKey;
167	  if (wantsMod && !primary) return false;
168	  if (!wantsMod && !wantsCtrl && primary) return false;
169	  // When `Mod` is wanted the literal-Ctrl gate is redundant (Mod already
170	  // accepts Ctrl); skip it so a pure ⌘ press isn't disqualified.
171	  if (!wantsMod && wantsCtrl && !event.ctrlKey) return false;
172	  if (!wantsMod && !wantsCtrl && event.ctrlKey) return false;
173	  if (wantsAlt !== Boolean(event.altKey)) return false;
174	  if (wantsShift !== Boolean(event.shiftKey)) return false;
175	
176	  // `parseShortcut` returns the trailing segment verbatim ("?", "/", "Tab").
177	  // Compare case-insensitively because `KeyboardEvent.key` is lowercase for
178	  // printable keys but `"Enter"` / `"Tab"` for the named ones.
179	  return parsed.key.toLowerCase() === event.key.toLowerCase();
180	}
181	
182	export function shortcutHints(
183	  commandId: EditorCommandId,
184	  platform: ShortcutPlatform = shortcutPlatform(),
185	): string[] {
186	  return keybindingsForCommand(commandId).map((binding) =>
187	    formatShortcut(binding.shortcut, platform),
188	  );
189	}
