191	export interface KeybindingListEntry {
192	  commandId: EditorCommandId;
193	  label: string;
194	  description: string;
195	  group: string;
196	  shortcuts: string[];
197	}
198	
199	/** Registry-backed rows consumed by both shortcut UIs. */
200	export function keybindingList(
201	  platform: ShortcutPlatform = shortcutPlatform(),
202	): KeybindingListEntry[] {
203	  const commands = new Map(
204	    EDITOR_COMMANDS.map((command) => [command.id, command]),
205	  );
206	  const ids = [
207	    ...new Set(EDITOR_KEYBINDINGS.map((binding) => binding.commandId)),
208	  ];
209	  return ids.map((commandId) => {
210	    const command = commands.get(commandId)!;
211	    return {
212	      commandId,
213	      label: command.label,
214	      description: command.description,
215	      group: command.group,
216	      shortcuts: shortcutHints(commandId, platform),
217	    };
218	  });
219	}
