1	/**
2	 * Tiny per-email preference store for which sign-in method the writer
3	 * last used. Passkey becomes the default once the user has registered
4	 * one; OTP remains the default for new accounts and for accounts that
5	 * haven't set up a passkey yet.
6	 *
7	 * Lives in localStorage; SSR-safe (no-ops outside the browser). Keys
8	 * are namespaced under `twyne.auth.` so we never collide with the rest
9	 * of the app's persisted state.
10	 */
11	
12	export type SignInMethod = "passkey" | "otp";
13	
14	const STORAGE_KEY = "twyne.auth.preferredMethod";
15	
16	function getStorage(): Storage | null {
17	  if (typeof window === "undefined") return null;
18	  try {
19	    return window.localStorage ?? null;
20	  } catch {
21	    return null;
22	  }
23	}
24	
25	function readAll(): Record<string, SignInMethod> {
26	  const storage = getStorage();
27	  if (!storage) return {};
28	  try {
29	    const raw = storage.getItem(STORAGE_KEY);
30	    if (!raw) return {};
31	    const parsed = JSON.parse(raw);
32	    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
33	      return parsed as Record<string, SignInMethod>;
34	    }
35	  } catch {
36	    // Corrupted blob — wipe and start fresh rather than blocking sign-in.
37	    try {
38	      storage.removeItem(STORAGE_KEY);
39	    } catch {
40	      /* storage may be locked down (private mode, etc.) — ignore. */
41	    }
42	  }
43	  return {};
44	}
45	
46	function writeAll(records: Record<string, SignInMethod>): void {
47	  const storage = getStorage();
48	  if (!storage) return;
49	  try {
50	    storage.setItem(STORAGE_KEY, JSON.stringify(records));
51	  } catch {
52	    /* storage full / disabled — preference is a hint, not a requirement. */
53	  }
54	}
