56	/** Lowercased so `Foo@…` and `foo@…` resolve to the same entry. */
57	function normalize(email: string): string {
58	  return email.trim().toLowerCase();
59	}
60	
61	/** Returns the preferred method for this email, or `null` if unknown. */
62	export function getPreferredMethod(email: string): SignInMethod | null {
63	  const key = normalize(email);
64	  if (!key) return null;
65	  return readAll()[key] ?? null;
66	}
67	
68	/** Persist the method the user just used to sign in. */
69	export function setPreferredMethod(email: string, method: SignInMethod): void {
70	  const key = normalize(email);
71	  if (!key) return;
72	  const records = readAll();
73	  records[key] = method;
74	  writeAll(records);
75	}
76	
77	/**
78	 * Forget the preference for an email. Called when a user explicitly
79	 * removes their passkey, or when a stored value gets out of sync.
80	 */
81	export function clearPreferredMethod(email: string): void {
82	  const key = normalize(email);
83	  if (!key) return;
84	  const records = readAll();
85	  delete records[key];
86	  writeAll(records);
87	}
