import { readFileSync, writeFileSync } from "node:fs";
const FILE = "src/global.css";
let css = readFileSync(FILE, "utf8");

// Shadows are cast, not inked: on a dark ground they must still darken, while
// a border or background mixed from --color-ink correctly follows the ink.
// Rewrite --color-ink to --shade only inside shadow-ish declarations.
const PROPS = /(^|[;{]\s*)((?:-webkit-)?(?:box-shadow|text-shadow)|filter)(\s*:\s*)/gm;
let out = "";
let cursor = 0;
let count = 0;
for (const m of css.matchAll(PROPS)) {
  const valueStart = m.index + m[0].length;
  let end = css.indexOf(";", valueStart);
  if (end === -1) end = css.indexOf("}", valueStart);
  if (end === -1) continue;
  const value = css.slice(valueStart, end);
  const swapped = value.replace(/var\(--color-ink\)/g, () => {
    count += 1;
    return "var(--shade)";
  });
  out += css.slice(cursor, valueStart) + swapped;
  cursor = end;
}
out += css.slice(cursor);
writeFileSync(FILE, out);
console.log(`re-pointed ${count} shadow mixes at --shade`);
EOF
