1	/**
2	 * The editorial palette, in one place.
3	 *
4	 * Three lists, because these are three different jobs with incompatible
5	 * requirements, and one list trying to serve all of them is how a palette goes
6	 * wrong:
7	 *
8	 *   - **Ink** — identity and accent. Persona colours, annotation chips,
9	 *     underlines. Read as a small area of colour against paper, so mustard and
10	 *     blush belong here even though neither is legible as body text.
11	 *   - **Text** — colour applied to prose. Every entry clears WCAG AA (4.5:1)
12	 *     against the manuscript's paper, which rules out the light half of the
13	 *     ink list; the amber and sage here are deliberately darkened cousins of
14	 *     the accent colours rather than the accents themselves.
15	 *   - **Highlight** — pale tints that sit *behind* text which must stay
16	 *     readable. A saturated highlighter turns a sentence into a smear. Word
17	 *     and Docs make the same split for the same reason.
18	 *
19	 * `palette.test.ts` checks the contrast rather than trusting the eye, because
20	 * "is this readable" is exactly the kind of judgement that drifts.
21	 *
22	 * Every swatch carries both a `cssVar` and a `hex`, and which one a caller
23	 * uses is not a matter of taste:
24	 *
25	 *   - **The editor writes `hex` into marks.** A mark styled
26	 *     `background-color: var(--color-mustard)` renders correctly in the app
27	 *     and renders *nothing* in an exported standalone HTML file, which has no
28	 *     such custom property defined. Colour that survives leaving the app has
29	 *     to be a literal.
30	 *   - **Chrome uses `cssVar`**, so a future theme can move it.
31	 *
32	 * Server-side rasterisers (`og-image.ts`) can only ever use `hex`; they run in
33	 * Node with no stylesheet at all.
34	 */
35	
36	export interface Swatch {
37	  /** Stable identifier, safe to persist. */
38	  id: string;
39	  /** Human label, used for the accessible name. */
40	  label: string;
41	  /** Literal colour. What gets written into a document. */
42	  hex: string;
43	  /** Theme reference. What gets used for app chrome. */
44	  cssVar: string;
45	}
