56	  { id: "vermilion", label: "Vermilion", hex: "#c1272d", cssVar: "var(--color-vermilion)" },
57	  { id: "mustard", label: "Mustard", hex: "#d4a017", cssVar: "var(--color-mustard)" },
58	  { id: "cobalt", label: "Cobalt", hex: "#2c4a7c", cssVar: "var(--color-cobalt)" },
