61	  { id: "sage", label: "Sage", hex: "#8a9a5b", cssVar: "var(--color-sage)" },
62	  { id: "blush", label: "Blush", hex: "#e8a598", cssVar: "var(--color-blush)" },
63	  { id: "ink", label: "Ink", hex: "#1f1b16", cssVar: "var(--color-ink)" },
64	];
