66	/**
67	 * Colours offered for prose.
68	 *
69	 * Darkened cousins of the accent hues rather than the accents themselves:
70	 * mustard at #d4a017 scores 2.0:1 against paper and is simply not text, however
71	 * good it looks as a badge. Everything here clears 4.5:1.
72	 */
73	export const TEXT_SWATCHES: readonly Swatch[] = [
74	  { id: "ink", label: "Ink", hex: "#1f1b16", cssVar: "var(--color-ink)" },
75	  { id: "vermilion", label: "Vermilion", hex: "#c1272d", cssVar: "var(--color-vermilion)" },
76	  { id: "cobalt", label: "Cobalt", hex: "#2c4a7c", cssVar: "var(--color-cobalt)" },
77	  // No "forest" here: #5b7a3a scores 4.16 against paper, just under AA, and
78	  // it is the same hue as olive below. One green, dark enough to read.
79	  { id: "olive", label: "Olive", hex: "#556134", cssVar: "var(--color-text-olive)" },
