86	 * Pale tints for highlighting, one per ink hue so the palettes read as the
87	 * same family. Each is light enough that the manuscript's ink (#1f1b16) still
88	 * clears WCAG AA on top of it.
89	 */
90	export const HIGHLIGHT_SWATCHES: readonly Swatch[] = [
91	  { id: "butter", label: "Butter", hex: "#fbeaa8", cssVar: "var(--color-highlight-butter)" },
92	  { id: "rose", label: "Rose", hex: "#f8d3d4", cssVar: "var(--color-highlight-rose)" },
93	  { id: "sky", label: "Sky", hex: "#cfe0f2", cssVar: "var(--color-highlight-sky)" },
94	  { id: "mint", label: "Mint", hex: "#d5e6c4", cssVar: "var(--color-highlight-mint)" },
95	  { id: "lilac", label: "Lilac", hex: "#dcdff4", cssVar: "var(--color-highlight-lilac)" },
96	  { id: "peach", label: "Peach", hex: "#fadfd5", cssVar: "var(--color-highlight-peach)" },
97	];
