99	/** The manuscript's body ink, for contrast checks against a highlight. */
100	export const MANUSCRIPT_INK = "#1f1b16";
101	
102	export type PaletteKind = "ink" | "text" | "highlight";
103	
104	export function swatchesFor(kind: PaletteKind): readonly Swatch[] {
105	  if (kind === "highlight") return HIGHLIGHT_SWATCHES;
106	  if (kind === "text") return TEXT_SWATCHES;
107	  return INK_SWATCHES;
108	}
109	
110	/** Look a swatch up by the literal colour stored in a document. */
111	export function swatchByHex(
112	  hex: string,
113	  kind: PaletteKind,
114	): Swatch | undefined {
115	  const want = hex.trim().toLowerCase();
116	  return swatchesFor(kind).find((s) => s.hex.toLowerCase() === want);
117	}
118	
119	/* ── Contrast, so a colour choice cannot quietly break readability ── */
120	
121	export function parseHex(hex: string): { r: number; g: number; b: number } | null {
122	  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
123	  if (!m) return null;
124	  let body = m[1];
125	  if (body.length === 3) {
126	    body = body
127	      .split("")
128	      .map((c) => c + c)
129	      .join("");
130	  }
131	  return {
132	    r: parseInt(body.slice(0, 2), 16),
133	    g: parseInt(body.slice(2, 4), 16),
134	    b: parseInt(body.slice(4, 6), 16),
135	  };
136	}
137	
138	/** Relative luminance, per WCAG 2.x. */
139	export function relativeLuminance(hex: string): number {
140	  const rgb = parseHex(hex);
141	  if (!rgb) return 0;
142	  const channel = (v: number) => {
143	    const s = v / 255;
144	    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
145	  };
146	  return (
147	    0.2126 * channel(rgb.r) + 0.7152 * channel(rgb.g) + 0.0722 * channel(rgb.b)
148	  );
149	}
150	
151	/** WCAG contrast ratio between two colours, 1 to 21. */
152	export function contrastRatio(a: string, b: string): number {
153	  const la = relativeLuminance(a);
154	  const lb = relativeLuminance(b);
155	  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
156	  return (hi + 0.05) / (lo + 0.05);
157	}
158	
159	/**
160	 * Pick black or white for text sitting on an arbitrary background.
161	 *
162	 * Needed because the picker accepts any colour the writer likes, including
163	 * one dark enough that the manuscript's own ink disappears into it.
164	 */
165	export function readableInkOn(background: string): string {
166	  return contrastRatio(background, MANUSCRIPT_INK) >= 4.5
167	    ? MANUSCRIPT_INK
168	    : "#ffffff";
169	}
170	
171	/** Normalise anything the colour input might hand back to `#rrggbb`. */
172	export function normalizeHex(value: string): string | null {
173	  const rgb = parseHex(value);
174	  if (!rgb) return null;
175	  const hex = (n: number) => n.toString(16).padStart(2, "0");
176	  return `#${hex(rgb.r)}${hex(rgb.g)}${hex(rgb.b)}`;
177	}
