import { expect, test, type Page } from "@playwright/test";

async function seedFolio(page: Page, html: string) {
  await page.goto("/");
  await page.evaluate(
    async ({ html }) => {
      const db: IDBDatabase = await new Promise((resolve, reject) => {
        const req = indexedDB.open("twyne", 2);
        req.onupgradeneeded = () => {
          const d = req.result;
          for (const [name, keyPath] of [
            ["folios", "id"],
            ["folio-content", "folioId"],
            ["brief", "folioId"],
            ["comments", "id"],
            ["personas", "id"],
            ["meta", "key"],
            ["ai-settings", "key"],
            ["lix-blob", "key"],
            ["voice-notes", "id"],
          ] as const) {
            if (!d.objectStoreNames.contains(name)) {
              d.createObjectStore(name, { keyPath });
            }
          }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });
      const now = Date.now();
      const id = "e2e-probe";
      await new Promise<void>((resolve, reject) => {
        const t = db.transaction(
          ["folios", "folio-content", "meta"],
          "readwrite",
        );
        t.objectStore("folios").put({
          id,
          name: "Probe",
          type: "draft",
          createdAt: now,
          updatedAt: now,
        });
        t.objectStore("folio-content").put({ folioId: id, html, updatedAt: now });
        t.objectStore("meta").put({
          key: "active-folio-id",
          value: id,
          updatedAt: now,
        });
        t.oncomplete = () => resolve();
        t.onerror = () => reject(t.error);
      });
    },
    { html },
  );
}

async function openEditor(page: Page, html: string) {
  await seedFolio(page, html);
  await page.goto("/editor/");
  await expect(page.locator(".ProseMirror")).toBeVisible({ timeout: 20_000 });
  await page.waitForFunction(
    () => (window as any).__twynePagination?.measureCount > 0,
    undefined,
    { timeout: 20_000 },
  );
}

async function setFont(page: Page, label: string, size?: string) {
  await page.getByRole("button", { name: "Type options", exact: true }).click();
  await page
    .getByRole("combobox", { name: "Font family" })
    .selectOption({ label });
  if (size) {
    await page.getByRole("combobox", { name: "Font size" }).selectOption(size);
  }
}

const DOC =
  "<h1>Chapter One</h1><p>First paragraph here.</p><p>Second paragraph here.</p>";

test.describe("PROBE", () => {
  test("A: select-all across whole document", async ({ page }) => {
    await openEditor(page, DOC);
