/** What the reader actually sees, letter by letter where it matters. */
async function report(page: Page, label: string) {
  await page.waitForTimeout(600);
  const data = await page.locator(".ProseMirror").evaluate((root) => {
    const paras = Array.from(root.querySelectorAll("p, h1"));
    return paras.map((el) => {
      const span = el.querySelector("span:not([data-section-drag-handle])");
      const cs = getComputedStyle(el);
      const ss = span ? getComputedStyle(span) : null;
      const fl = getComputedStyle(el, "::first-letter");
      return {
        tag: el.tagName,
        text: (el.textContent ?? "").slice(0, 22),
        blockFont: cs.fontFamily.split(",")[0],
        blockSize: cs.fontSize,
        spanFont: ss?.fontFamily.split(",")[0] ?? null,
        spanSize: ss?.fontSize ?? null,
        firstLetterFont: fl.fontFamily.split(",")[0],
        firstLetterSize: fl.fontSize,
        styleAttr: span?.getAttribute("style") ?? null,
      };
    });
  });
  console.log(`\n=== ${label} ===`);
  for (const row of data) console.log(JSON.stringify(row));
}

