/* ─────────────────────────────────────────────────────────────
 * Compositor's stick, on a narrow screen
 *
 * The toolbar carries around forty controls in seven groups. Left
 * to wrap, that is six stacked rows on a phone — roughly a third
 * of the viewport, in an app whose entire product is vertical
 * space for prose. Below `sm` it becomes one horizontally
 * scrolling row instead.
 *
 * Groups never split or squash: `flex: none` keeps each control
 * at its natural width so a scroll never lands mid-group, and
 * scroll-snap parks the strip on a group boundary. The scrollbar
 * is deliberately left visible — it is the affordance, and the
 * one thing the floating table toolbar was missing when writers
 * could not find "Delete table".
 * ───────────────────────────────────────────────────────────── */
.twyne-toolbar > * {
  flex: none;
}

@media (max-width: 639px) {
  .twyne-toolbar {
    scroll-snap-type: x proximity;
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--color-paper-3) transparent;
  }
  .twyne-toolbar > * {
    scroll-snap-align: start;
  }
  /* Touch targets. 0.25rem of padding is fine for a mouse and not for a
     thumb; this brings each control to a 34px box without changing the
     desktop metrics above. */
  .twyne-toolbar .tool-btn {
    padding: 0.4rem 0.55rem;
  }
}

